const KEY="taskapp.trello-mockup.v1";
const sample=()=>({title:"タスクボード",lists:[{id:"todo",title:"未着手",cards:[{id:"c1",title:"要件を確認する"},{id:"c2",title:"画面を作る"}]},{id:"doing",title:"進行中",cards:[{id:"c3",title:"ドラッグ&ドロップを実装する"}]},{id:"done",title:"完了",cards:[{id:"c4",title:"プロトタイプを作成する"}]}]});
let board=load(),dragged,pending;const lists=document.querySelector("#lists"),status=document.querySelector("#status"),dialog=document.querySelector("#confirm-dialog");const uid=p=>`${p}-${crypto.randomUUID?.()||Date.now()}`;const byList=id=>board.lists.find(x=>x.id===id);const byCard=(l,id)=>byList(l).cards.find(x=>x.id===id);const esc=s=>{const d=document.createElement("div");d.textContent=s;return d.innerHTML};
function load(){try{const x=JSON.parse(localStorage.getItem(KEY));if(x&&Array.isArray(x.lists))return x}catch{}return sample()}function save(){try{localStorage.setItem(KEY,JSON.stringify(board));return true}catch{notice("保存できませんでした。ブラウザの保存設定を確認してください。",true);return false}}function notice(t="",err=false){status.textContent=t;status.classList.toggle("error",err)}function commit(t){save();render();notice(t)}
function render(){document.querySelector("#board-title").textContent=board.title;lists.innerHTML=board.lists.map(listView).join("")+addListView()}function listView(l){return `<article class="list"><header class="list-head"><h2 class="list-title">${esc(l.title)}</h2>${menu("list",l.id)}</header><div class="cards" data-drop="${l.id}">${l.cards.map(c=>cardView(l,c)).join("")}</div>${addCardView(l.id)}</article>`}function menu(kind,listId,cardId=""){const move=kind==="card"?`<button data-action="move-menu" data-list="${listId}" data-card="${cardId}">移動…</button>`:"";return `<details class="menu"><summary class="menu-button" aria-label="操作メニュー">•••</summary><div class="popup"><button data-action="edit-${kind}" data-list="${listId}" data-card="${cardId}">編集</button>${move}<button data-action="delete-${kind}" data-list="${listId}" data-card="${cardId}">削除</button></div></details>`}function cardView(l,c){return `<article class="card" draggable="true" data-list="${l.id}" data-card="${c.id}"><span>${esc(c.title)}</span><span class="card-menu">${menu("card",l.id,c.id)}</span></article>`}function addCardView(id){return `<div data-add-card="${id}"><button class="add-card-trigger" data-action="open-card-form" data-list="${id}">＋ カードを追加</button></div>`}function addListView(){return `<section class="add-list"><button class="add-list-trigger" data-action="open-list-form">＋ 別のリストを追加</button></section>`}
function form(type,listId=""){const label=type==="list"?"リスト名":"カード名";return `<form class="add-form" data-form="${type}" data-list="${listId}" novalidate><input name="title" aria-label="${label}" placeholder="${label}を入力" autofocus><p class="error-text"></p><div class="form-actions"><button>追加</button><button class="cancel" type="button" data-action="close-form">×</button></div></form>`}function openForm(type,listId){const holder=type==="list"?lists.lastElementChild:document.querySelector(`[data-add-card="${listId}"]`);holder.innerHTML=form(type,listId);holder.querySelector("input").focus()}function edit(kind,listId,cardId){const target=kind==="list"?byList(listId):byCard(listId,cardId);const node=kind==="list"?document.querySelector(`.list:has([data-list="${listId}"]) .list-head`):document.querySelector(`.card[data-card="${cardId}"]`);node.innerHTML=`<input class="inline-input" value="${esc(target.title)}" aria-label="名前を編集">`;const input=node.querySelector("input");input.focus();input.select();input.addEventListener("keydown",e=>{if(e.key==="Enter"){const t=input.value.trim();if(!t)return notice("名前を入力してください。",true);target.title=t;commit("名前を更新しました。")}if(e.key==="Escape")render()});input.addEventListener("blur",()=>render(),{once:true})}
function ask(type,list,card){pending={type,list,card};const item=card?byCard(list,card):byList(list);document.querySelector("#confirm-message").textContent=type==="list"?`「${item.title}」を削除します。含まれるカードも削除されます。`:`「${item.title}」を削除します。`;dialog.showModal()}function moveMenu(list,card){const current=board.lists.indexOf(byList(list));const choices=board.lists.map((x,i)=>`${i+1}: ${x.title}`).join("\n");const answer=prompt(`移動先を選んでください\n${choices}`,String(current+1));if(answer===null)return;const target=board.lists[Number(answer)-1];if(!target)return notice("有効な移動先を選んでください。",true);const source=byList(list),index=source.cards.findIndex(x=>x.id===card),[item]=source.cards.splice(index,1);target.cards.push(item);commit("カードを移動しました。")}
document.addEventListener("click",e=>{const b=e.target.closest("[data-action]");if(!b)return;const d=b.dataset;if(d.action==="open-card-form")openForm("card",d.list);if(d.action==="open-list-form")openForm("list");if(d.action==="close-form")render();if(d.action==="edit-list")edit("list",d.list);if(d.action==="edit-card")edit("card",d.list,d.card);if(d.action==="delete-list")ask("list",d.list);if(d.action==="delete-card")ask("card",d.list,d.card);if(d.action==="move-menu")moveMenu(d.list,d.card)});document.addEventListener("submit",e=>{if(!e.target.matches(".add-form"))return;e.preventDefault();const f=e.target,t=f.elements.title.value.trim();if(!t){f.querySelector(".error-text").textContent="名前を入力してください。";return}if(f.dataset.form==="list")board.lists.push({id:uid("list"),title:t,cards:[]});else byList(f.dataset.list).cards.push({id:uid("card"),title:t});commit("追加しました。")});
document.addEventListener("dragstart",e=>{const c=e.target.closest(".card");if(!c)return;dragged={list:c.dataset.list,card:c.dataset.card};c.classList.add("dragging")});document.addEventListener("dragend",e=>{e.target.closest(".card")?.classList.remove("dragging");document.querySelectorAll(".cards").forEach(x=>x.classList.remove("drop-target"));dragged=null});document.addEventListener("dragover",e=>{const area=e.target.closest(".cards");if(!area||!dragged)return;e.preventDefault();area.classList.add("drop-target")});document.addEventListener("drop",e=>{const area=e.target.closest(".cards");if(!area||!dragged)return;e.preventDefault();const from=byList(dragged.list),i=from.cards.findIndex(x=>x.id===dragged.card),[item]=from.cards.splice(i,1),to=byList(area.dataset.drop),before=e.target.closest(".card");let at=before?[...area.querySelectorAll(".card")].indexOf(before):to.cards.length;if(from===to&&i<at)at--;to.cards.splice(at,0,item);commit("カードを移動しました。")});dialog.addEventListener("close",()=>{if(dialog.returnValue!=="confirm"||!pending)return;const{type,list,card}=pending;if(type==="list")board.lists=board.lists.filter(x=>x.id!==list);else byList(list).cards=byList(list).cards.filter(x=>x.id!==card);pending=null;commit("削除しました。")});render();
